from typing import Set, List

class PowerGame:

	def __init__(self, n):
		self.friendships: List[int] = [0] * n
		self.surviving = n

	@staticmethod
	def _converted_params(u, v):
		(u, v) = sorted((u - 1, v - 1))
		return (u, v)

	def add_friendship(self, u, v):
		(u, v) = self._converted_params(u, v)
		if self.friendships[u] == 0:
			self.surviving -= 1
		self.friendships[u] += 1

	def remove_friendship(self, u, v):
		(u, v) = self._converted_params(u, v)
		self.friendships[u] -= 1
		if self.friendships[u] == 0:
			self.surviving += 1

	def calculate(self):
		return self.surviving

def main():
	(nobles, friendships) = map(int, input().split())
	power_game = PowerGame(nobles)
