class HST:

	def __init__(self, ascending=True):
		self._h = []
		self._q = set()
		self.ascending = ascending

	def push(self, v):
		if not self.ascending:
			v *= -1
		hp(self._h, v)
		self._q.add(v)

	def remove(self, v):
		if not self.ascending:
			v *= -1
		self._q.discard(v)

	def top(self):
		while self._h and self._h[0] not in self._q:
			hpp(self._h)
		if not self._h:
			res = -1
		else:
